"""Original pancreatic neoplasm and cyst questions."""
from qbank_authoring import question,ref,finalize
KY=ref('International Evidence-Based Kyoto IPMN Guidelines 2024','https://doi.org/10.1016/j.pan.2023.12.009')
EU=ref('European Evidence-Based Guidelines on Pancreatic Cystic Neoplasms','https://doi.org/10.1136/gutjnl-2018-316027')
NCI=ref('NCI PDQ: Pancreatic Cancer Treatment, Health Professional Version','https://www.cancer.gov/types/pancreatic/hp/pancreatic-treatment-pdq')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('A pancreatic cyst communicates with side branches of the main pancreatic duct and produces mucin. Which diagnosis is most likely?', 'Branch-duct intraductal papillary mucinous neoplasm',[
 ('Mucinous cystic neoplasm','MCN typically lacks duct communication and is defined histologically by ovarian-type stroma.'),('Serous cystic neoplasm','A serous lesion is generally nonmucinous and does not have the defining intraductal papillary phenotype.'),('Solid pseudopapillary neoplasm','This is a distinct solid/cystic tumor rather than a mucin-producing intraductal lesion.')],
 'Duct communication is a major classification clue', '**IPMN arises within the pancreatic duct system.**', ['Branch-duct, main-duct and mixed patterns have different risk profiles.','MRCP is useful for defining communication and duct anatomy.'], '**Classify before applying surveillance rules.**', ['A cyst label alone is not a malignancy risk category.','Nodules, duct diameter, symptoms and cytology refine the assessment.'], [['IPMN','Duct-related mucinous lesion'],['MCN','Ovarian-type stroma, usually no communication'],['Serous lesion','Usually nonmucinous']], [KY,EU], 'clinical_scenario')
q('A woman has a solitary mucinous cyst in the pancreatic tail. Which histological finding establishes the characteristic diagnosis of mucinous cystic neoplasm?', 'Ovarian-type stroma',[
 ('Granulocytic epithelial lesions','These are associated with type 2 autoimmune pancreatitis.'),('Intraductal papillary growth with a communicating main duct','This favors IPMN rather than the defining MCN stromal pattern.'),('Glycogen-rich cuboidal epithelial cells without mucin','This favors a serous cystic neoplasm.')],
 'MCN is a pathological entity with a characteristic stroma', '**Location and sex suggest the diagnosis, but ovarian-type stroma defines MCN.**', ['Most arise in the body or tail.','Duct communication is usually absent.'], '**Risk is assessed separately from cyst identity.**', ['Symptoms, size and nodules influence the case for resection.','An indeterminate pancreatic cyst should not be treated as proven MCN from one demographic clue.'], [['MCN','Mucinous epithelium plus ovarian-type stroma'],['IPMN','Intraductal papillary mucinous lesion'],['Serous neoplasm','Nonmucinous glycogen-rich cells']], [EU], 'clinical_scenario')
q('An incidental pancreatic lesion has a microcystic honeycomb appearance, a central scar and very low cyst-fluid CEA. Which diagnosis is favored?', 'Serous cystic neoplasm',[
 ('Mucinous cystic neoplasm','The classic MCN pattern is macrocystic and mucinous rather than honeycomb with a central scar.'),('Main-duct IPMN','This is characterized by involvement of the main pancreatic duct.'),('Pancreatic pseudocyst','A history of pancreatitis and a compatible fluid collection would be more supportive.')],
 'Recognize a classic low-risk cyst pattern', '**A confidently diagnosed serous lesion is usually benign.**', ['Atypical oligocystic or solid-appearing variants can be difficult to classify.','Low CEA supports nonmucinous fluid but is not independently definitive.'], '**Avoid automatic cancer surveillance or surgery for every incidental cyst.**', ['Symptoms, diagnostic uncertainty and compression can alter management.','A secure diagnosis matters before stopping surveillance.'], [['Serous pattern','Microcysts and possible central scar'],['Mucinous pattern','Different epithelial biology'],['Uncertain pattern','Further characterization']], [EU], 'clinical_scenario')
q('What does a high pancreatic cyst-fluid CEA concentration primarily help identify?', 'Mucinous rather than nonmucinous cyst type',[
 ('The presence of invasive cancer with certainty','CEA is not a reliable discriminator between low-grade mucinous disease and cancer.'),('Whether a mucinous lesion is MCN rather than IPMN','Both may have elevated CEA; anatomy and pathology are needed.'),('The precise stage of a pancreatic malignancy','CEA is not an anatomical staging test.')],
 'Cyst identity and malignant grade are different questions', '**Cyst-fluid CEA can support mucinous classification, with imperfect accuracy.**', ['It must be interpreted with imaging and cytology.','An isolated high value should not trigger a cancer diagnosis.'], '**Look elsewhere for high-risk features.**', ['Enhancing nodules, a solid component, major duct dilation and malignant cytology matter.','Fluid sampling is most useful when the result could change management.'], [['CEA','Helps classify mucinous fluid'],['Cytology','May identify high-grade or malignant cells'],['Imaging','Defines anatomy and risk features']], [EU])
q('Which is a high-risk stigma under the 2024 Kyoto IPMN guidelines?', 'An enhancing mural nodule measuring 6 mm',[
 ('A 3-mm enhancing mural nodule','A nodule below 5 mm is a worrisome feature rather than this high-risk size criterion.'),('A main pancreatic duct measuring 7 mm','A duct of at least 5 but below 10 mm is a worrisome feature.'),('A cyst measuring 32 mm with no other findings','Size of at least 30 mm is a worrisome feature, not by itself a high-risk stigma.')],
 'Use named-guideline thresholds precisely', '**An enhancing mural nodule of at least 5 mm or a solid component is a Kyoto high-risk stigma.**', ['Obstructive jaundice from a head IPMN, a main duct of at least 10 mm and suspicious/positive cytology are other high-risk findings.','The final decision still includes fitness and operative consequences.'], '**A worrisome feature triggers further evaluation rather than being synonymous with cancer.**', ['EUS can clarify a suspected nodule.','Distinguish true enhancement from adherent mucus.'], [['Nodule ≥5 mm','High-risk stigma'],['Nodule <5 mm','Worrisome feature'],['Main duct 5 to <10 mm','Worrisome feature']], [KY])
q('A fit patient has IPMN-related main pancreatic duct dilation to 11 mm without an alternative obstructing lesion. How is this classified in the Kyoto framework?', 'A high-risk stigma warranting expert surgical assessment',[
 ('A low-risk finding requiring no further assessment','Main-duct dilation at this level is a major concern.'),('A worrisome feature only because all duct diameters below 15 mm have identical risk','The high-risk threshold is 10 mm.'),('Proof that the lesion is a serous cystadenoma','Duct dilation does not establish a serous diagnosis.')],
 'Main-duct caliber is a risk signal', '**A main duct of at least 10 mm is a high-risk stigma when attributable to IPMN.**', ['Exclude other causes such as an obstructing mass or stone.','Mixed and main-duct disease need careful whole-gland assessment.'], '**Discuss resection in the context of patient fitness and anatomy.**', ['High risk does not replace operative risk assessment.','The extent of duct involvement influences surgical planning.'], [['5 to <10 mm','Worrisome duct feature'],['≥10 mm','High-risk duct feature'],['Alternative obstruction','Investigate cause']], [KY], 'clinical_scenario')
q('Which change in a branch-duct IPMN is a worrisome feature in the 2024 Kyoto guideline?', 'Cyst growth of at least 2.5 mm per year',[
 ('A stable 12-mm cyst with no nodules or symptoms','This does not by itself meet the listed growth criterion.'),('An isolated 0.5-mm difference between scans using different techniques','Small measurement variation should not automatically be interpreted as meaningful growth.'),('A fall in serum amylase to normal','Amylase normalization is not an IPMN progression marker.')],
 'Measure a trend with comparable imaging', '**Growth rate can add risk information beyond a single diameter.**', ['The Kyoto worrisome threshold is at least 2.5 mm per year.','Measurement consistency and the time interval are important.'], '**Evaluate new features together.**', ['New or worsening diabetes, pancreatitis and elevated CA 19-9 can also be relevant.','A worrisome feature prompts more detailed assessment, often with EUS.'], [['Stable small cyst','Lower-risk surveillance pathway'],['Documented rapid growth','Worrisome feature'],['Measurement noise','Confirm comparability']], [KY])
q('A 22-mm branch-duct IPMN has no high-risk stigmata, but the patient develops new diabetes and the cyst wall becomes thickened and enhancing. What is the best interpretation?', 'The small size does not negate new worrisome features; expert reassessment is needed',[
 ('All cysts below 30 mm are automatically free of malignant potential','Risk assessment is not based on size alone.'),('New diabetes proves invasive cancer without further testing','It is a risk feature, not a definitive tissue diagnosis.'),('The wall finding proves a benign pseudocyst','A thickened enhancing wall is not specific for a pseudocyst.')],
 'Risk is multidimensional', '**Symptoms, metabolism, wall features and duct anatomy can matter even in a relatively small cyst.**', ['Confirm that diabetes is new or worsening in the relevant interval.','Review for nodules, duct change and alternative pancreatic disease.'], '**Use the findings to choose additional evaluation.**', ['EUS and selective sampling can refine a management-changing uncertainty.','Balance potential benefit against age, comorbidity and surgical feasibility.'], [['Diameter alone','Incomplete assessment'],['New worrisome findings','Escalate characterization'],['Cancer diagnosis','Requires integrated evidence']], [KY], 'clinical_scenario')
q('When is EUS-guided pancreatic cyst sampling most appropriate?', 'When imaging leaves a clinically important uncertainty and the result is expected to change management',[
 ('For every tiny incidental cyst regardless of risk or consequences','Sampling adds procedural risk and may provide no actionable information.'),('Only after invasive cancer is already definitively proven','Sampling can help resolve selected diagnostic uncertainties before then.'),('As a replacement for all cross-sectional imaging','Imaging supplies essential whole-pancreas and duct information.')],
 'Perform a test to resolve an actionable question', '**Fluid analysis and cytology have strengths and limitations.**', ['Cytology can be specific but insensitive.','A nondiagnostic sample does not automatically mean benign disease.'], '**Combine methods rather than treating one fluid result as the entire diagnosis.**', ['An obvious surgical indication may not need cyst aspiration merely to repeat the conclusion.','Consider bleeding risk, access and infection precautions under the procedural protocol.'], [['Imaging','Anatomy and morphology'],['EUS','Detailed local assessment'],['Sampling','Selected management-changing uncertainty']], [EU])
q('A young woman has a large encapsulated pancreatic mass with solid and hemorrhagic cystic areas. Histology shows pseudopapillary structures and nuclear beta-catenin. Which diagnosis is favored?', 'Solid pseudopapillary neoplasm',[
 ('Serous cystic neoplasm','This has glycogen-rich cuboidal epithelium rather than the pseudopapillary nuclear beta-catenin pattern.'),('Mucinous cystic neoplasm','Ovarian-type stroma and mucinous epithelium are characteristic instead.'),('Pancreatic ductal adenocarcinoma','Infiltrative gland-forming carcinoma has a different typical pathological pattern.')],
 'A distinct tumor can have both solid and cystic components', '**Solid pseudopapillary neoplasm has malignant potential despite often indolent behavior.**', ['Young women are the characteristic demographic, not an absolute requirement.','Hemorrhage can explain the mixed imaging appearance.'], '**Refer for specialist surgical assessment.**', ['Localized disease often has a favorable outcome after complete resection.','Do not classify it as a simple post-inflammatory cyst merely because fluid is present.'], [['Pseudopapillary architecture','Characteristic morphology'],['Nuclear beta-catenin','Supports diagnosis'],['Localized tumor','Resection assessment']], [NCI,EU], 'clinical_scenario')
q('A pancreatic head mass causes painless progressive jaundice and dilation of both the common bile duct and pancreatic duct. What does the double-duct sign indicate?', 'A concerning periampullary or pancreatic obstructing lesion that requires definitive evaluation',[
 ('A sign specific enough to prove pancreatic adenocarcinoma without further work-up','Other malignant and benign causes can produce it.'),('A finding that excludes ampullary malignancy','Ampullary lesions can obstruct both ducts.'),('A normal age-related change requiring no assessment in a jaundiced patient','The symptomatic obstructive pattern is clinically significant.')],
 'A strong anatomical clue is not a tissue diagnosis', '**Obstruction near the common drainage region can dilate both systems.**', ['Pancreatic-protocol imaging and EUS help identify the cause and stage disease.','Cholangitis or severe symptomatic obstruction can change drainage priorities.'], '**Define resectability before choosing the treatment sequence.**', ['Vascular contact and metastatic disease are crucial.','CA 19-9 cannot replace anatomical staging or tissue assessment when required.'], [['Double-duct sign','Shared distal obstruction clue'],['Pancreatic-protocol imaging','Staging and anatomy'],['EUS','Lesion and tissue evaluation']], [NCI], 'clinical_scenario')
q('What is the main purpose of pancreatic-protocol multiphase CT in suspected pancreatic ductal adenocarcinoma?', 'Define the primary lesion, vascular relationships and distant disease to assess resectability',[
 ('Prove the tumor genotype from enhancement alone','Imaging does not establish actionable molecular variants.'),('Replace all tissue diagnosis before systemic treatment','Histological confirmation is ordinarily required before nonsurgical anticancer therapy.'),('Determine malignancy solely from serum enzyme levels','Enzymes do not provide anatomical staging.')],
 'Stage the disease before planning a major operation', '**Resectability depends on anatomy and disease extent, not tumor diameter alone.**', ['Arterial involvement, venous reconstructability and metastases affect treatment selection.','Liver or peritoneal disease may change the intent of treatment.'], '**Integrate imaging with expert multidisciplinary review.**', ['EUS-guided tissue sampling can establish diagnosis when needed.','An indeterminate lesion may require additional MRI or targeted assessment.'], [['Local anatomy','Vessels and adjacent structures'],['Distant staging','Potential metastatic disease'],['Tissue','Histological diagnosis']], [NCI])
q('Which statement about serum CA 19-9 in suspected pancreatic cancer is correct?', 'It is a contextual marker; cholestasis can elevate it and some patients do not produce it',[
 ('A normal result excludes pancreatic ductal adenocarcinoma','Sensitivity is insufficient and nonsecretor phenotypes exist.'),('An elevated result in obstructive jaundice proves metastatic disease','Benign cholestasis can raise the marker and it does not define stage.'),('It is a sufficiently accurate stand-alone population screening test','Its performance is inadequate for that purpose.')],
 'Interpret tumor markers in their biological context', '**CA 19-9 is neither a stand-alone diagnostic test nor an anatomical stage.**', ['Biliary obstruction can confound the value.','Lewis-antigen-related nonproduction can yield a misleadingly low result.'], '**Use trends only alongside the clinical and imaging picture.**', ['A post-drainage value can be more interpretable in obstructive jaundice.','A discordant result should prompt reassessment rather than override stronger evidence.'], [['Elevated with cholestasis','Potential confounding'],['Normal result','Does not exclude malignancy'],['Serial values','Adjunct to disease assessment']], [NCI])
q('A pancreatic tumor has reconstructible short-segment portal/superior mesenteric venous involvement and no metastases. What is the most appropriate general principle?', 'Venous involvement does not automatically make the tumor permanently unresectable; obtain expert resectability review',[
 ('Any venous contact is equivalent to distant metastatic disease','Local vascular involvement and metastasis are different categories.'),('Vascular anatomy has no relevance if the tumor is small','Even a small tumor may involve critical vessels.'),('Proceed to surgery without considering systemic therapy or reconstruction feasibility','Treatment sequencing and technical feasibility need multidisciplinary assessment.')],
 'Vascular involvement has degrees and technical consequences', '**Reconstructibility and the pattern of vessel contact help distinguish resectable, borderline and locally advanced disease.**', ['Arterial and venous involvement are not interchangeable.','Definitions vary somewhat across frameworks and require specialist interpretation.'], '**Select the sequence that offers the best prospect of an oncologically useful resection.**', ['Borderline disease often receives neoadjuvant treatment.','Restaging includes biology and distant progression, not merely a size change.'], [['Reconstructible venous segment','May permit a surgical pathway'],['Unreconstructible critical anatomy','Can preclude resection'],['Distant metastasis','Different disease category']], [NCI], 'clinical_scenario')
q('Before starting neoadjuvant chemotherapy for a suspected pancreatic adenocarcinoma, what is ordinarily required?', 'Histological or cytological confirmation of malignancy',[
 ('An elevated CA 19-9 alone','A marker cannot reliably establish the diagnosis.'),('A positive fecal elastase result','Exocrine insufficiency is not proof of malignancy.'),('A response to empiric chemotherapy as the diagnostic test','Systemic treatment should not be used as a substitute for diagnosis.')],
 'Systemic anticancer treatment needs a secure diagnosis', '**EUS-guided tissue acquisition is commonly used for a pancreatic lesion.**', ['A metastatic site may be sampled when it provides a safer or more informative target.','Adequate material can also support molecular studies.'], '**Distinguish this from selected upfront surgical pathways.**', ['A clearly resectable highly suspicious lesion may sometimes proceed to surgery without preoperative biopsy after expert review.','That exception is not the standard before neoadjuvant therapy.'], [['Before systemic treatment','Tissue confirmation ordinarily required'],['Selected upfront operation','Preoperative biopsy may not always be required'],['Nondiagnostic sample','Reassess and resample when needed']], [NCI])
q('What is the usual oncological operation for a resectable pancreatic ductal adenocarcinoma confined to the pancreatic head?', 'Pancreaticoduodenectomy',[
 ('Distal pancreatectomy alone','This removes the body/tail and would not adequately address a head primary.'),('Simple tumor enucleation','Ductal adenocarcinoma requires an oncological resection rather than local shelling-out.'),('Cholecystectomy alone','This does not remove the pancreatic malignancy.')],
 'The operation follows the location and oncological anatomy', '**A head primary generally requires pancreaticoduodenectomy with appropriate regional oncological clearance.**', ['Body/tail tumors usually require a different resection.','Fitness, margins, vascular anatomy and distant staging determine suitability.'], '**Surgery is one component of multimodal care.**', ['Perioperative systemic treatment is selected according to stage and fitness.','Nutritional and exocrine/endocrine consequences require follow-up.'], [['Head/uncinate primary','Pancreaticoduodenectomy pathway'],['Body/tail primary','Distal pancreatic resection pathway'],['Metastatic disease','Systemic/palliative treatment focus']], [NCI])
q('A patient with good performance status has recovered adequately after pancreatic ductal adenocarcinoma resection. Which regimen is an established adjuvant option for a suitably fit patient?', 'Modified FOLFIRINOX',[
 ('Rituximab monotherapy','This targets CD20-positive B-cell disease, not routine pancreatic adenocarcinoma.'),('Octreotide alone','This is not standard adjuvant treatment for ductal adenocarcinoma.'),('Imatinib alone without a relevant tumor indication','This is not a routine adjuvant pancreatic ductal regimen.')],
 'Postoperative systemic therapy addresses occult disease', '**A fit patient may benefit from an intensive multiagent adjuvant regimen.**', ['Modified FOLFIRINOX combines fluoropyrimidine, folinate, irinotecan and oxaliplatin.','Alternatives such as gemcitabine-based therapy can be more suitable for other patients.'], '**Assess recovery and treatment tolerance before selection.**', ['Performance status, organ function and neuropathy matter.','Do not extrapolate a regimen for neuroendocrine tumors or GIST to ductal cancer.'], [['Fit postoperative patient','Consider modified FOLFIRINOX'],['Less suitable for intensive therapy','Consider an alternative regimen'],['Other pancreatic histology','Different treatment framework']], [NCI])
q('A patient has metastatic pancreatic ductal adenocarcinoma with a germline BRCA2 variant and no progression after more than 16 weeks of first-line platinum-based chemotherapy. Which maintenance option has an established indication?', 'Olaparib',[
 ('Imatinib irrespective of tumor profiling','There is no general pancreatic ductal maintenance indication based on BRCA2 for imatinib.'),('Tamoxifen','Hormone receptor treatment is not the BRCA-directed strategy here.'),('Rituximab','CD20-directed therapy is not the relevant mechanism.')],
 'Match a maintenance strategy to a defined molecular and treatment context', '**PARP inhibition exploits a homologous-recombination repair vulnerability.**', ['The established setting requires germline BRCA-associated metastatic disease with control on first-line platinum therapy.','This should not be generalized to every pancreatic cancer or every DNA-repair variant.'], '**Discuss benefit, toxicity and goals of maintenance treatment.**', ['Monitor for hematological and other adverse effects.','The molecular result must be accurately classified and interpreted.'], [['Germline BRCA plus platinum-controlled metastatic disease','Olaparib maintenance consideration'],['Progression on induction','Different next-line assessment'],['Unselected disease','No blanket PARP indication']], [NCI], 'clinical_scenario')
q('Why is molecular testing relevant in advanced pancreatic ductal adenocarcinoma?', 'Rare actionable alterations can change treatment selection, including DNA-repair and mismatch-repair findings',[
 ('Every pancreatic tumor has an identical actionable genotype','Actionable findings occur only in subsets.'),('Imaging enhancement can replace molecular testing','Imaging does not define these alterations.'),('A negative common-marker result proves there are no inherited cancer implications','Appropriate germline assessment is a separate consideration.')],
 'A common histological diagnosis can contain distinct treatment subgroups', '**Germline and tumor testing answer related but different questions.**', ['Inherited variants can affect relatives as well as treatment.','Tumor testing may identify a tissue-agnostic treatment indication in a small subgroup.'], '**Interpret results through an oncology and genetics pathway.**', ['Variant significance and the exact approved setting matter.','A molecular possibility is not a guarantee of benefit.'], [['Germline test','Inherited predisposition and selected treatment relevance'],['Tumor profile','Somatic actionable alterations'],['Uncertain variant','Do not treat as proven actionable']], [NCI])
q('A patient with unresectable pancreatic cancer has painful obstructive jaundice and pruritus. What is the role of biliary drainage?', 'Palliate obstruction and support subsequent care when appropriate, without treating the systemic cancer itself',[
 ('It eradicates metastatic disease if bilirubin normalizes','Mechanical decompression does not remove distant tumor.'),('It is never useful because the tumor is unresectable','Symptom relief and treatment feasibility can be important benefits.'),('It replaces all analgesic and nutritional care','Palliative care addresses multiple needs, not just the bile duct.')],
 'Palliation can have a clear anatomical target', '**An endoscopic or alternative drainage route can relieve a clinically significant obstruction.**', ['Cholangitis increases urgency.','The choice of stent and route depends on anticipated course and anatomy.'], '**Keep symptom control integrated with the overall treatment plan.**', ['Pain, gastric outlet symptoms, malnutrition and psychosocial needs also matter.','Explain the purpose of drainage without implying cancer cure.'], [['Biliary drainage','Relieves obstruction'],['Systemic therapy','Treats disseminated tumor biology'],['Supportive care','Addresses broader symptom burden']], [NCI], 'clinical_scenario')
q('What is the best general statement about pancreatic cancer screening in an asymptomatic average-risk adult?', 'Routine population screening is not established; surveillance is reserved for selected high-risk groups in expert programs',[
 ('Annual CA 19-9 is a validated universal screening strategy','The marker has inadequate screening accuracy.'),('Every incidental cyst requires immediate total pancreatectomy','Cyst risk is heterogeneous and the operation has major consequences.'),('A family history can never justify specialist risk assessment','Selected familial or genetic risk can warrant expert surveillance assessment.')],
 'Low disease prevalence amplifies false-positive harm', '**Screening and diagnostic evaluation of symptoms are different activities.**', ['A symptomatic patient with weight loss and jaundice needs investigation regardless of screening policy.','Selected inherited/familial risk is assessed through dedicated programs.'], '**Use risk-based specialist pathways.**', ['MRI/MRCP and EUS may be used in high-risk surveillance programs.','CA 19-9 alone is not a substitute for an appropriate program.'], [['Average-risk asymptomatic adult','No routine population program'],['Selected familial/genetic risk','Expert surveillance assessment'],['Concerning symptoms','Diagnostic work-up']], [ref('AGA Pancreas Cancer Screening in High-Risk Individuals','https://gastro.org/clinical-guidance/pancreas-cancer-screening-in-high-risk-individuals/')])
q('A pancreatic cyst was discovered before any pancreatitis episode and has an enhancing mural nodule. What is the most important diagnostic caution?', 'Do not call it a pseudocyst solely because pancreatitis later occurred',[
 ('Pancreatitis excludes a cystic neoplasm','IPMN and other neoplasms can themselves precipitate pancreatitis.'),('Any cyst with elevated amylase must be a benign pseudocyst','Duct-communicating neoplasms can also have high cyst-fluid amylase.'),('A nodule is diagnostic of sterile inflammatory fluid','A true enhancing nodule raises neoplastic concern.')],
 'Chronology and morphology prevent a circular diagnosis', '**A pancreatic neoplasm can cause pancreatitis rather than result from it.**', ['Review prior imaging and the original timing.','Differentiate debris or mucus from a vascularized mural nodule.'], '**Characterize the lesion before choosing drainage or surveillance.**', ['Inappropriate cyst drainage can delay a neoplastic diagnosis.','MRCP, EUS and selective sampling may be needed.'], [['Cyst predates pancreatitis','Reconsider pseudocyst assumption'],['True enhancing nodule','Neoplastic risk feature'],['High cyst amylase','Not specific for pseudocyst']], [EU,KY], 'clinical_scenario')
q('A confidently diagnosed asymptomatic serous cystic neoplasm is found in a patient with substantial comorbidity. What management principle is appropriate?', 'Avoid oncological resection solely for the diagnosis; assess symptoms, certainty and competing risks',[
 ('Treat it as main-duct IPMN regardless of morphology','These are different biological entities.'),('Use cyst-fluid CEA to stage invasive cancer in every serous lesion','CEA is not a staging test and the premise does not establish invasive disease.'),('Recommend total pancreatectomy for all serous lesions','This imposes disproportionate morbidity for a generally benign lesion.')],
 'Biology and treatment burden must both enter the decision', '**A secure serous diagnosis has a very different risk profile from a high-risk mucinous lesion.**', ['Compression symptoms or uncertain diagnosis can justify further evaluation.','Asymptomatic patients often need no operative treatment.'], '**Match follow-up to the degree of diagnostic confidence.**', ['Atypical morphology may warrant expert reassessment.','Do not prolong a surveillance program that cannot produce a meaningful management benefit.'], [['Secure asymptomatic serous diagnosis','Usually conservative'],['Symptomatic compression','Consider intervention'],['Uncertain cyst identity','Clarify before de-escalation']], [EU], 'clinical_scenario')
q('An older frail patient with a small low-risk branch-duct IPMN would not accept or tolerate pancreatic surgery. What should guide surveillance decisions?', 'Discuss whether continued imaging can provide meaningful benefit given life expectancy, fitness and preferences',[
 ('Continue indefinite surveillance automatically regardless of any possible action','Surveillance is most useful when detection can change management.'),('Declare that the cyst can never progress because the patient is frail','Patient frailty changes treatment benefit, not cyst biology.'),('Apply one mandatory stopping age to every patient without considering risk','Age alone does not capture disease risk, comorbidity or preferences.')],
 'Surveillance should lead to a plausible beneficial action', '**Cyst risk must be weighed against competing mortality and the consequences of intervention.**', ['Guideline stopping options are conditional, not universal proof of zero future risk.','Younger or genetically high-risk patients may require a different approach.'], '**Make the purpose of follow-up explicit.**', ['Consider whether a changed result would lead to treatment or a useful symptom plan.','Document the discussion rather than allowing automatic scanning to substitute for a decision.'], [['Fit and actionable risk','Surveillance may benefit'],['No feasible intervention','Reconsider surveillance value'],['New concerning symptoms','Diagnostic reassessment may still be appropriate']], [KY,EU], 'clinical_scenario')

